import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"PUF","description":"","frontmatter":{"title":"PUF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/puf.md","filePath":"cs/puf.md","lastUpdated":1789023840000}'),h={name:"cs/puf.md"};function u(_,a,f,m,P,E){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="puf" tabindex="-1">PUF <a class="header-anchor" href="#puf" aria-label="Permalink to &quot;PUF&quot;">​</a></h1><div class="epigraph"><p>物理不可克隆函数把制造差异变成挑战–响应：像指纹，难复制。它可作设备身份与密钥派生，但可靠性、老化与建模攻击要进合同。</p><footer>—— Gassend, Clarke, van Dijk and Devadas, Silicon Physical Random Functions, CCS 2002</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/fault-injection">故障</a>扰计算。缺口是<strong>用物理差异当身份</strong>而不是存密钥。本课 PUF 直觉，不写建模攻击步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>密钥要存 NVM，可被读出。PUF：挑战进、响应出，模糊提取得到稳定密钥。缺口是误码、温度、机器学习建模。</p><h3 id="不是完善保密" tabindex="-1">不是完善保密 <a class="header-anchor" href="#不是完善保密" aria-label="Permalink to &quot;不是完善保密&quot;">​</a></h3><p>PUF 是硬件身份候选，要模糊提取与限次挑战。</p><p><span class="marginnote">Gassend et al. 2002。禁止克隆实验。Spectre 缓解下一课回微结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画挑战响应。对照 HSM 存钥。下一课 Spectre 缓解与代价。</p>',12)),(e(),n(c,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E6%8C%91%E6%88%98%22%5D%20--%3E%20PHY%5B%22%E5%88%B6%E9%80%A0%E5%B7%AE%E5%BC%82%22%5D%0A%20%20PHY%20--%3E%20RSP%5B%22%E5%93%8D%E5%BA%94%22%5D%0A%20%20RSP%20--%3E%20FE%5B%22%E6%A8%A1%E7%B3%8A%E6%8F%90%E5%8F%96%E5%BE%97%E9%92%A5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>设备身份可不上电存储。微结构泄漏下一课是另一物理/共享硬件轴。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写建模攻击。Spectre 缓解下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>故障扰计算；PUF 用差异当指纹。</li><li>模糊提取把噪声响应收成密钥。</li><li>老化与建模要进威胁模型。</li><li>下一课 Spectre 缓解。</li><li>出处：Gassend, Clarke, van Dijk and Devadas, 2002。</li></ul>',8))])}const A=l(h,[["render",u]]);export{b as __pageData,A as default};
